import streamDeck from "@elgato/streamdeck";

import { PrintStatus } from "./actions/print-status";

// "info" evita volcar tokens/telemetria completa a los logs en uso normal (usa "trace" para depurar).
streamDeck.logger.setLevel("info");

// Red de seguridad: una rejection/exception sin capturar mata el proceso de
// Node entero (Stream Deck deja la tecla en el icono generico de "accion
// rota" sin ninguna pista de por que). Mejor loguearlo y seguir vivo.
process.on("unhandledRejection", (reason) => {
	streamDeck.logger.error(`unhandledRejection: ${reason instanceof Error ? reason.stack ?? reason.message : String(reason)}`);
});
process.on("uncaughtException", (err) => {
	streamDeck.logger.error(`uncaughtException: ${err.stack ?? err.message}`);
});

streamDeck.actions.registerAction(new PrintStatus());

streamDeck.connect();
