import streamDeck, {
	action,
	DidReceiveSettingsEvent,
	KeyAction,
	KeyDownEvent,
	SingletonAction,
	WillAppearEvent,
	WillDisappearEvent,
} from "@elgato/streamdeck";

import { BambuCloudService } from "../bambu-cloud-service";
import { ERROR_COLOR, renderKeyImage, renderPlaceholder, VIEW_COUNT } from "../render";
import type { BambuTelemetry, CloudRegion } from "../types";

type PrintStatusSettings = {
	userToken?: string;
	deviceSerial?: string;
	region?: CloudRegion;
};

function credentialsKey(settings: PrintStatusSettings): string | null {
	if (!settings.userToken || !settings.deviceSerial) return null;
	return `${settings.userToken}::${settings.deviceSerial}::${settings.region ?? "us"}`;
}

interface Connection {
	service: BambuCloudService;
	key: string;
	lastTelemetry: BambuTelemetry | null;
	view: number;
}

// Nunca dejar una promesa de setImage/showAlert sin capturar: una rejection
// no atendida puede tumbar el proceso del plugin entero (Node mata el proceso
// en unhandledRejection), dejando la tecla en el icono generico de "accion
// rota" sin ninguna pista de por que.
async function safeSetImage(keyAction: KeyAction<PrintStatusSettings>, image: string, label: string): Promise<void> {
	try {
		await keyAction.setImage(image);
	} catch (err) {
		streamDeck.logger.error(`[print-status:${label}] setImage fallo: ${(err as Error).message}`);
	}
}

async function safeShowAlert(keyAction: KeyAction<PrintStatusSettings>, label: string): Promise<void> {
	try {
		await keyAction.showAlert();
	} catch (err) {
		streamDeck.logger.error(`[print-status:${label}] showAlert fallo: ${(err as Error).message}`);
	}
}

/**
 * Muestra el estado en vivo de una impresora Bambu Lab (progreso, temperaturas,
 * ETA), leyendo la telemetria desde Bambu Cloud (ver ../bambu-cloud-service.ts).
 * Cada pulsacion rota entre vistas (ver ../render.ts): estado -> temperaturas -> tiempo/capa.
 */
@action({ UUID: "com.alejandrocabo.bambuconnect.print-status" })
export class PrintStatus extends SingletonAction<PrintStatusSettings> {
	// Una conexion MQTT por tecla visible, indexada por el id de instancia de la accion.
	private readonly connections = new Map<string, Connection>();

	override async onWillAppear(ev: WillAppearEvent<PrintStatusSettings>): Promise<void> {
		streamDeck.logger.info(`[print-status] onWillAppear id=${ev.action.id}`);
		if (!ev.action.isKey()) return;
		await this.sync(ev.action, ev.payload.settings);
	}

	override onWillDisappear(ev: WillDisappearEvent<PrintStatusSettings>): void {
		this.teardown(ev.action.id);
	}

	override async onDidReceiveSettings(ev: DidReceiveSettingsEvent<PrintStatusSettings>): Promise<void> {
		if (!ev.action.isKey()) return;
		await this.sync(ev.action, ev.payload.settings);
	}

	override onKeyDown(ev: KeyDownEvent<PrintStatusSettings>): void {
		if (!ev.action.isKey()) return;
		const conn = this.connections.get(ev.action.id);
		if (!conn) return;
		conn.view = (conn.view + 1) % VIEW_COUNT;
		void safeSetImage(ev.action, renderKeyImage(conn.lastTelemetry, conn.view), ev.action.id);
		conn.service.requestPushAll();
	}

	private async sync(keyAction: KeyAction<PrintStatusSettings>, settings: PrintStatusSettings): Promise<void> {
		const actionId = keyAction.id;
		const key = credentialsKey(settings);
		const existing = this.connections.get(actionId);

		if (!key) {
			if (existing) this.teardown(actionId);
			await safeSetImage(keyAction, renderPlaceholder("Configura\nel token"), actionId);
			return;
		}

		if (existing?.key === key) return; // ya conectado con las mismas credenciales
		if (existing) this.teardown(actionId);

		const service = new BambuCloudService({
			userToken: settings.userToken!,
			deviceSerial: settings.deviceSerial!,
			region: settings.region ?? "us",
		});
		const conn: Connection = { service, key, lastTelemetry: null, view: 0 };
		this.connections.set(actionId, conn);

		service.on("telemetry", (t: BambuTelemetry) => {
			conn.lastTelemetry = t;
			void safeSetImage(keyAction, renderKeyImage(t, conn.view), actionId);
		});
		service.on("error", (err: Error) => {
			streamDeck.logger.error(`[print-status:${actionId}] ${err.message}`);
			void safeSetImage(keyAction, renderPlaceholder("Error de\nconexion", ERROR_COLOR), actionId);
			void safeShowAlert(keyAction, actionId);
		});

		await safeSetImage(keyAction, renderPlaceholder("Conectando..."), actionId);
		try {
			await service.connect();
		} catch (err) {
			streamDeck.logger.error(`[print-status:${actionId}] ${(err as Error).message}`);
			await safeSetImage(keyAction, renderPlaceholder("Error de\ntoken", ERROR_COLOR), actionId);
		}
	}

	private teardown(actionId: string): void {
		const existing = this.connections.get(actionId);
		if (!existing) return;
		existing.service.disconnect();
		this.connections.delete(actionId);
	}
}
