// Cliente MQTT para Bambu Cloud.
//
// Protocolo replicado a partir de BambuHelper (C++/ESP32, Keralots/BambuHelper):
//   - broker:   `${region}.mqtt.bambulab.com` : 8883, TLS (us.mqtt.bambulab.com o
//               cn.mqtt.bambulab.com; las cuentas EU tambien usan el broker "us")
//               ver BambuHelper/src/bambu_cloud.cpp:getBambuBroker()
//   - clientId: "bblp_" + sufijo aleatorio (evita colisiones de sesion en el broker)
//               ver BambuHelper/src/bambu_mqtt.cpp:1240 (reconnect())
//   - username: "u_<uid>", uid extraido del JWT (claim uid/sub/user_id) o, si el
//               token no es JWT, vía GET /v1/user-service/my/profile
//               ver BambuHelper/src/bambu_cloud.cpp:cloudExtractUserId / cloudFetchUserId
//   - password: el userToken (JWT) tal cual
//   - keepalive: 30s en modo cloud (BAMBU_CLOUD_KEEPALIVE)
//   - subscribe: `device/${serial}/report`  (telemetria)
//   - publish:   `device/${serial}/request` (comandos, p.ej. pushall)
//               ver BambuHelper/src/bambu_mqtt.cpp:requestPushall()
import mqtt, { MqttClient } from 'mqtt';
import { EventEmitter } from 'node:events';
import { randomBytes } from 'node:crypto';
import {
  AmsState,
  AmsTray,
  AmsUnit,
  BambuCloudServiceOptions,
  BambuTelemetry,
  CloudRegion,
  GcodeState,
} from './types';

const BAMBU_PORT = 8883;
const BAMBU_CLOUD_KEEPALIVE = 30;
const AMS_TRAYS_PER_UNIT = 4;

function brokerHost(region: CloudRegion): string {
  return region === 'cn' ? 'cn.mqtt.bambulab.com' : 'us.mqtt.bambulab.com';
}

function apiBase(region: CloudRegion): string {
  return region === 'cn' ? 'https://api.bambulab.cn' : 'https://api.bambulab.com';
}

// El JWT usa base64url; Buffer.from(..., 'base64') de Node ya tolera '-' y '_'
// pero no el padding, así que lo normalizamos igualmente por claridad.
function decodeJwtUserId(token: string): string | null {
  const parts = token.split('.');
  if (parts.length < 2) return null;
  try {
    const payloadJson = Buffer.from(parts[1], 'base64url').toString('utf8');
    const payload = JSON.parse(payloadJson);
    const uid = payload.uid ?? payload.sub ?? payload.user_id;
    if (uid === undefined || uid === null || uid === '') return null;
    return `u_${uid}`;
  } catch {
    return null;
  }
}

// Fallback para tokens no-JWT: igual que cloudFetchUserId() en bambu_cloud.cpp.
async function fetchUserIdFromProfile(token: string, region: CloudRegion): Promise<string | null> {
  const url = `${apiBase(region)}/v1/user-service/my/profile`;
  const res = await fetch(url, {
    headers: {
      Authorization: `Bearer ${token}`,
      'User-Agent': 'bambu_network_agent/01.09.05.01',
      'X-BBL-Client-Name': 'OrcaSlicer',
      'X-BBL-Client-Type': 'slicer',
    },
  });
  if (!res.ok) return null;
  const body = (await res.json()) as { uidStr?: string; uid?: string | number };
  const uid = body.uidStr ?? body.uid;
  if (uid === undefined || uid === null || uid === '') return null;
  return `u_${uid}`;
}

function parseGcodeState(raw: unknown): GcodeState {
  switch (raw) {
    case 'IDLE':
    case 'RUNNING':
    case 'PAUSE':
    case 'PREPARE':
    case 'FINISH':
    case 'FAILED':
      return raw;
    case undefined:
    case '':
    case 'UNKNOWN':
      return 'UNKNOWN';
    default:
      return 'OTHER';
  }
}

function isPrintingState(state: GcodeState): boolean {
  return state === 'RUNNING' || state === 'PAUSE' || state === 'PREPARE';
}

// Los ventiladores "legacy" (*_fan_speed) llegan en escala 0-15; fan_gear
// (PWM 0-255 empaquetado) no se replica aqui porque no aporta nada nuevo a
// nivel de protocolo para un boton de Stream Deck: basta con el porcentaje.
function fanPercent(v: unknown): number | null {
  if (v === undefined || v === null) return null;
  const n = typeof v === 'string' ? parseInt(v, 10) : Number(v);
  if (Number.isNaN(n)) return null;
  return Math.round((n / 15) * 100);
}

function parseAms(printObj: Record<string, any>): AmsState | null {
  const amsRoot = printObj.ams;
  if (!amsRoot) return null;

  const unitsRaw: any[] = Array.isArray(amsRoot.ams) ? amsRoot.ams : [];
  const units: AmsUnit[] = unitsRaw.map((u) => {
    const trays: AmsTray[] = (Array.isArray(u.tray) ? u.tray : []).map((t: any, i: number) => {
      const present = typeof t.tray_type === 'string' && t.tray_type.length > 0;
      const color: string | null =
        t.tray_color || (Array.isArray(t.cols) && t.cols.length > 0 ? t.cols[0] : null) || null;
      const type: string | null = present ? t.tray_sub_brands || t.tray_type : null;
      const remainRaw = t.remain !== undefined ? Number(t.remain) : -1;
      return {
        index: t.id !== undefined ? Number(t.id) : i,
        present,
        type,
        color,
        remainPercent: remainRaw > 0 ? remainRaw : null,
      };
    });
    return {
      id: u.id !== undefined ? Number(u.id) : -1,
      humidityPercent: u.humidity !== undefined ? Number(u.humidity) : null,
      tempC: u.temp !== undefined ? Number(u.temp) : null,
      trays,
    };
  });

  // Sentinelas del propio protocolo: tray_now 254 = carrete externo, 255 = ninguna.
  const trayNowRaw = amsRoot.tray_now !== undefined ? Number(amsRoot.tray_now) : null;
  let activeTrayIndex: number | null = null;
  if (trayNowRaw !== null && trayNowRaw >= 0 && trayNowRaw < AMS_TRAYS_PER_UNIT * units.length) {
    activeTrayIndex = trayNowRaw;
  }

  const vt = printObj.vt_tray;
  const externalSpoolActive = trayNowRaw === 254;
  const externalSpool: AmsState['externalSpool'] =
    vt && typeof vt.tray_type === 'string' && vt.tray_type.length > 0
      ? {
          present: true,
          type: vt.tray_sub_brands || vt.tray_type,
          color: vt.tray_color || (Array.isArray(vt.cols) && vt.cols.length > 0 ? vt.cols[0] : null) || null,
        }
      : null;

  return { present: true, units, activeTrayIndex, externalSpoolActive, externalSpool };
}

function parseTelemetry(deviceSerial: string, msg: any): BambuTelemetry | null {
  const print = msg?.print;
  if (!print) return null;

  const gcodeState = parseGcodeState(print.gcode_state);

  // chamber_temper viene directo en la mayoria de modelos; en los que tienen
  // control de camara (ctc), el valor llega empaquetado como (target << 16) | actual.
  let chamberTempC: number | null = null;
  if (typeof print.chamber_temper === 'number') {
    chamberTempC = print.chamber_temper;
  } else if (print.ctc?.info?.temp !== undefined) {
    chamberTempC = Number(print.ctc.info.temp) & 0xffff;
  }

  let lightOn: boolean | null = null;
  if (Array.isArray(print.lights_report)) {
    const chamberLight = print.lights_report.find((l: any) => l.node === 'chamber_light');
    if (chamberLight) lightOn = chamberLight.mode !== 'off';
  }

  return {
    timestamp: Date.now(),
    deviceSerial,
    gcodeState,
    printing: isPrintingState(gcodeState),
    progressPercent: typeof print.mc_percent === 'number' ? print.mc_percent : null,
    remainingMinutes: typeof print.mc_remaining_time === 'number' ? print.mc_remaining_time : null,
    layerNum: typeof print.layer_num === 'number' ? print.layer_num : null,
    totalLayers: typeof print.total_layer_num === 'number' ? print.total_layer_num : null,
    subtaskName: typeof print.subtask_name === 'string' ? print.subtask_name : null,
    nozzleTempC: typeof print.nozzle_temper === 'number' ? print.nozzle_temper : null,
    nozzleTargetC: typeof print.nozzle_target_temper === 'number' ? print.nozzle_target_temper : null,
    bedTempC: typeof print.bed_temper === 'number' ? print.bed_temper : null,
    bedTargetC: typeof print.bed_target_temper === 'number' ? print.bed_target_temper : null,
    chamberTempC,
    speedLevel: typeof print.spd_lvl === 'number' ? print.spd_lvl : null,
    wifiSignalDbm: print.wifi_signal !== undefined ? parseInt(String(print.wifi_signal), 10) : null,
    fans: {
      coolingPercent: fanPercent(print.cooling_fan_speed),
      auxPercent: fanPercent(print.big_fan1_speed),
      chamberPercent: fanPercent(print.big_fan2_speed),
      heatbreakPercent: fanPercent(print.heatbreak_fan_speed),
    },
    lightOn,
    ams: parseAms(print),
    raw: msg,
  };
}

/**
 * Eventos emitidos:
 *  - 'connected'    ()                    conectado y suscrito al topic report
 *  - 'disconnected' ()                    conexion cerrada
 *  - 'error'        (err: Error)
 *  - 'message'      (raw: unknown)        JSON crudo tal cual llega del broker
 *  - 'telemetry'    (data: BambuTelemetry) telemetria ya parseada
 */
export class BambuCloudService extends EventEmitter {
  private readonly options: Required<Omit<BambuCloudServiceOptions, 'userId'>>;
  private userId: string | null;
  private client: MqttClient | null = null;
  private pushallSeq = 0;

  constructor(options: BambuCloudServiceOptions) {
    super();
    this.options = {
      userToken: options.userToken,
      deviceSerial: options.deviceSerial,
      region: options.region ?? 'us',
      rejectUnauthorized: options.rejectUnauthorized ?? true,
      pushAllOnConnect: options.pushAllOnConnect ?? true,
      debug: options.debug ?? false,
    };
    this.userId = options.userId ?? null;
  }

  private log(...args: unknown[]): void {
    if (this.options.debug) console.log('[BambuCloudService]', ...args);
  }

  async connect(): Promise<void> {
    if (!this.userId) {
      this.userId = decodeJwtUserId(this.options.userToken);
      if (!this.userId) {
        this.log('el token no parece un JWT decodificable, probando /profile...');
        this.userId = await fetchUserIdFromProfile(this.options.userToken, this.options.region);
      }
      if (!this.userId) {
        throw new Error(
          'No se pudo resolver el userId de Bambu a partir del token (fallo el decode JWT y la API de perfil)',
        );
      }
      this.log('userId resuelto:', this.userId);
    }

    const host = brokerHost(this.options.region);
    const clientId = `bblp_${randomBytes(6).toString('hex')}`;

    this.log(`conectando a mqtts://${host}:${BAMBU_PORT} como ${this.userId} (clientId=${clientId})`);

    this.client = mqtt.connect({
      host,
      port: BAMBU_PORT,
      protocol: 'mqtts',
      protocolVersion: 4,
      username: this.userId,
      password: this.options.userToken,
      clientId,
      keepalive: BAMBU_CLOUD_KEEPALIVE,
      rejectUnauthorized: this.options.rejectUnauthorized,
      reconnectPeriod: 5000,
    });

    this.client.on('connect', () => {
      const topic = `device/${this.options.deviceSerial}/report`;
      this.client!.subscribe(topic, (err) => {
        if (err) {
          this.emit('error', err);
          return;
        }
        this.log('suscrito a', topic);
        this.emit('connected');
        if (this.options.pushAllOnConnect) this.requestPushAll();
      });
    });

    this.client.on('reconnect', () => this.log('reconectando...'));
    this.client.on('close', () => {
      this.log('conexion cerrada');
      this.emit('disconnected');
    });
    this.client.on('error', (err) => {
      this.log('error:', err.message);
      this.emit('error', err);
      // Token invalido/expirado: reintentar no lo arregla, solo martillea el broker.
      if (/not authorized|bad user name or password|bad credentials/i.test(err.message)) {
        this.client?.end(true);
      }
    });

    this.client.on('message', (_topic, payload) => {
      let msg: unknown;
      try {
        msg = JSON.parse(payload.toString('utf8'));
      } catch (err) {
        this.log('no se pudo parsear el mensaje JSON:', (err as Error).message);
        return;
      }
      this.emit('message', msg);
      const telemetry = parseTelemetry(this.options.deviceSerial, msg);
      if (telemetry) this.emit('telemetry', telemetry);
    });
  }

  /** Pide un snapshot completo del estado (equivalente a bambu_mqtt.cpp:requestPushall). */
  requestPushAll(): void {
    if (!this.client?.connected) return;
    const topic = `device/${this.options.deviceSerial}/request`;
    const payload = JSON.stringify({
      pushing: {
        sequence_id: String(this.pushallSeq++),
        command: 'pushall',
        version: 1,
        push_target: 1,
      },
    });
    this.client.publish(topic, payload);
    this.log('pushall enviado');
  }

  disconnect(): void {
    this.client?.end(true);
    this.client = null;
  }
}
