// Genera la imagen de la tecla como SVG (Stream Deck acepta un string SVG
// directo en setImage). Todo se dibuja aqui en vez de usar setTitle: fondo
// oscuro + anillo de progreso + iconos vectoriales, en vez del titulo de
// texto plano sobre el fondo gris por defecto.
import type { BambuTelemetry, GcodeState } from "./types";

const SIZE = 144;

const BG = "#15171c";
const RING_TRACK = "#2a2e36";
const TEXT = "#f2f3f5";
const MUTED = "#8a92a1";
export const ERROR_COLOR = "#e0433d";

const STATE_COLOR: Record<GcodeState, string> = {
	RUNNING: "#00ae42", // verde Bambu
	PAUSE: "#f2b134",
	PREPARE: "#3aa0ff",
	FINISH: "#00ae42",
	FAILED: "#e0433d",
	IDLE: "#5b6472",
	UNKNOWN: "#5b6472",
	OTHER: "#5b6472",
};

const STATE_LABEL: Record<GcodeState, string> = {
	RUNNING: "IMPRIMIENDO",
	PAUSE: "PAUSADO",
	PREPARE: "PREPARANDO",
	FINISH: "COMPLETADO",
	FAILED: "ERROR",
	IDLE: "LISTA",
	UNKNOWN: "SIN DATOS",
	OTHER: "-",
};

function esc(text: string): string {
	return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function frame(inner: string): string {
	return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SIZE} ${SIZE}">
		<rect width="${SIZE}" height="${SIZE}" rx="20" fill="${BG}"/>
		${inner}
	</svg>`;
}

// Icono central segun el estado del gcode: play / pausa / check / cruz /
// standby / reloj de arena. Coordenadas ya pensadas para quedar centradas
// dentro del anillo de progreso (centro en 72,60) - sin transforms, porque
// "transform-origin" via CSS no lo soportan todos los renderizadores SVG.
function stateIcon(state: GcodeState, color: string): string {
	switch (state) {
		case "RUNNING":
			return `<polygon points="63,47 63,73 86,60" fill="${color}"/>`;
		case "PAUSE":
			return `<rect x="60" y="45" width="9" height="30" rx="3" fill="${color}"/>
				<rect x="75" y="45" width="9" height="30" rx="3" fill="${color}"/>`;
		case "FINISH":
			return `<path d="M55 61 L66 72 L90 46" stroke="${color}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round" fill="none"/>`;
		case "FAILED":
			return `<path d="M55 43 L89 77 M89 43 L55 77" stroke="${color}" stroke-width="7" stroke-linecap="round"/>`;
		case "PREPARE":
			return `<path d="M57 43 H87 L72 60 L87 77 H57 L72 60 Z" fill="none" stroke="${color}" stroke-width="6" stroke-linejoin="round"/>`;
		case "IDLE":
			return `<circle cx="72" cy="64" r="15" fill="none" stroke="${color}" stroke-width="6"/>
				<line x1="72" y1="42" x2="72" y2="54" stroke="${color}" stroke-width="6" stroke-linecap="round"/>`;
		default:
			return `<text x="72" y="72" font-family="Arial, sans-serif" font-size="34" font-weight="700" fill="${color}" text-anchor="middle">?</text>`;
	}
}

// Anillo de progreso: track de fondo siempre visible; arco relleno solo con
// datos de progreso reales (imprimiendo, o 100% al completar).
function progressRing(state: GcodeState, progressPercent: number | null, color: string): string {
	const r = 44;
	const cx = 72;
	const cy = 60;
	const circumference = 2 * Math.PI * r;
	const track = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${RING_TRACK}" stroke-width="9"/>`;

	let pct: number | null = null;
	if (state === "RUNNING" || state === "PAUSE" || state === "PREPARE") pct = progressPercent ?? 0;
	else if (state === "FINISH") pct = 100;
	if (pct === null) return track;

	const offset = circumference * (1 - Math.min(100, Math.max(0, pct)) / 100);
	const arc = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="9"
		stroke-linecap="round" stroke-dasharray="${circumference}" stroke-dashoffset="${offset}"
		transform="rotate(-90 ${cx} ${cy})"/>`;
	return track + arc;
}

function centerLabel(text: string, y: number, size: number, color: string, weight = "700"): string {
	return `<text x="72" y="${y}" font-family="Arial, sans-serif" font-size="${size}" font-weight="${weight}"
		fill="${color}" text-anchor="middle">${esc(text)}</text>`;
}

// ── Vista 1: estado + anillo de progreso ────────────────────────────────────
function renderStatusView(t: BambuTelemetry): string {
	const color = STATE_COLOR[t.gcodeState];
	const ring = progressRing(t.gcodeState, t.progressPercent, color);
	const icon = stateIcon(t.gcodeState, color);

	// El porcentaje solo aporta info mientras imprime o al terminar; en el
	// resto de estados el icono ya lo dice todo, así que se omite la línea
	// (un "--" ahi solo añadía ruido visual).
	const showPercent = t.printing || t.gcodeState === "FINISH";
	const percent = t.gcodeState === "FINISH" ? 100 : (t.progressPercent ?? 0);
	const bottomText = showPercent ? centerLabel(`${percent}%`, 122, 26, TEXT) : "";
	const labelY = showPercent ? 137 : 126;
	const labelSize = showPercent ? 11 : 13;
	const label = centerLabel(STATE_LABEL[t.gcodeState], labelY, labelSize, MUTED, "600");

	return frame(`${ring}${icon}${bottomText}${label}`);
}

// ── Vista 2: temperaturas (boquilla + cama) ─────────────────────────────────
function nozzleIcon(color: string): string {
	return `<path d="M72 12 C83 29 91 40 91 51 A19 19 0 1 1 53 51 C53 40 61 29 72 12 Z" fill="${color}"/>`;
}

function bedIcon(color: string): string {
	return `<rect x="50" y="30" width="44" height="28" rx="3" fill="none" stroke="${color}" stroke-width="4"/>
		<line x1="50" y1="44" x2="94" y2="44" stroke="${color}" stroke-width="3"/>
		<line x1="65" y1="30" x2="65" y2="58" stroke="${color}" stroke-width="3"/>
		<line x1="80" y1="30" x2="80" y2="58" stroke="${color}" stroke-width="3"/>`;
}

function renderTempsView(t: BambuTelemetry): string {
	const accent = STATE_COLOR[t.gcodeState];
	const row = (iconSvg: string, current: number | null, target: number | null, y: number) => `
		<g transform="translate(16, ${y - 34}) scale(0.42)">${iconSvg}</g>
		<text x="58" y="${y + 8}" font-family="Arial, sans-serif" font-size="24" font-weight="700" fill="${TEXT}">${Math.round(current ?? 0)}&#176;</text>
		<text x="58" y="${y + 26}" font-family="Arial, sans-serif" font-size="12" fill="${MUTED}">objetivo ${Math.round(target ?? 0)}&#176;</text>`;

	return frame(`
		${centerLabel("TEMPERATURAS", 20, 11, MUTED, "600")}
		${row(nozzleIcon(accent), t.nozzleTempC, t.nozzleTargetC, 55)}
		${row(bedIcon(accent), t.bedTempC, t.bedTargetC, 105)}
	`);
}

// ── Vista 3: tiempo restante + capa actual ──────────────────────────────────
function clockIcon(color: string): string {
	return `<circle cx="72" cy="40" r="21" fill="none" stroke="${color}" stroke-width="4"/>
		<line x1="72" y1="40" x2="72" y2="27" stroke="${color}" stroke-width="4" stroke-linecap="round"/>
		<line x1="72" y1="40" x2="83" y2="47" stroke="${color}" stroke-width="4" stroke-linecap="round"/>`;
}

function layersIcon(color: string): string {
	return `<rect x="52" y="70" width="40" height="7" rx="2" fill="${color}"/>
		<rect x="52" y="81" width="40" height="7" rx="2" fill="${color}" opacity="0.65"/>
		<rect x="52" y="92" width="40" height="7" rx="2" fill="${color}" opacity="0.35"/>`;
}

function renderTimeView(t: BambuTelemetry): string {
	const accent = STATE_COLOR[t.gcodeState];
	const timeText = t.printing && t.remainingMinutes !== null ? `${t.remainingMinutes} min` : "--";
	const layerText = t.printing && t.totalLayers ? `${t.layerNum ?? 0} / ${t.totalLayers}` : "--";

	return frame(`
		${clockIcon(accent)}
		${centerLabel(timeText, 60, 15, TEXT)}
		${layersIcon(accent)}
		${centerLabel(layerText, 118, 15, TEXT)}
		${centerLabel("CAPA", 133, 10, MUTED, "600")}
	`);
}

const VIEWS: Array<(t: BambuTelemetry) => string> = [renderStatusView, renderTempsView, renderTimeView];
export const VIEW_COUNT = VIEWS.length;

export function renderKeyImage(telemetry: BambuTelemetry | null, view: number): string {
	if (!telemetry) return renderPlaceholder("Sin datos", MUTED);
	const renderer = VIEWS[((view % VIEW_COUNT) + VIEW_COUNT) % VIEW_COUNT];
	return renderer(telemetry);
}

export function renderPlaceholder(message: string, color: string = MUTED): string {
	const lines = message.split("\n");
	const startY = lines.length > 1 ? 96 : 110;
	const labels = lines.map((line, i) => centerLabel(line, startY + i * 20, 15, TEXT)).join("");
	return frame(`
		<circle cx="72" cy="60" r="6" fill="${color}"/>
		${labels}
	`);
}
